        var d = cm_n(cm_p(P, 'dir', 1));
        cm_cam(cam, { pre: 'var z=ios(cu),ww=Math.sin(t*2.3);',
            s: '1+' + cm_n(cm_p(P, 'a', 0.06)) + '*KM*z', sx: '1+0.03*KM*z*ww', sy: '1-0.026*KM*z*ww',
            skx: '2.2*KM*z*Math.sin(t*1.7)*' + d, rot: '0.8*KM*z*Math.sin(t*1.1+1)*' + d });
