    apply: function (cam, P) {
        cm_cam(cam, { pre: 'var q=oc(cu),A=H*' + cm_n(cm_p(P, 'a', 0.028)) + '*KM;', y: 'A*(1.2-1.6*q)', s: '1.035-0.02*q' });
    }
