        var ltr = !!d.right, xa = W * dc2_rr(0.06, 0.16, s, 3), xb = W * dc2_rr(0.84, 0.95, s, 4), tilt = dc2_rs(s, 5) * T * 0.35, bow = dc2_rs(s, 6) * T * 0.25;
        var K = 22, SN = 26, S = jzShapeLayer(ctx, 'brush stroke', 0, 0), hairs = [[], []], bn, band;
