                    var t = ta + (tb - ta) * i / m, tt = ltr ? t : 1 - t, taper = 1 - Math.pow(t, 3) * 0.55;
                    pts.push([jzLerp(xa, xb, tt), yc + tilt * (tt - 0.5) + bow * Math.sin(tt * Math.PI) + f * T * taper + dc2_rs(s, j, Math.round(t * SN), 8) * 0.8 * u]);
