    function angEx(i) { return OP + jzN(-90 + tilt) + '-SP/2+SP*' + jzN(i / N); }
    function sweep(g) { return db1_trim(ctx, g, ST, 'SP/3.6', null, jzN(tilt) + '-SP/2', OP); }
