    db1_trim(ctx, g2, ST, '100*ioc((t-0.35)/0.7)'); db1_st(g2, sc.sub, Math.max(1, 1.1 * u), 70, 2, 2);
    db1_gx(ctx, g2, 'ADBE Vector Position', ST, DR + '[-dr*0.6,0]');
