    var gh2 = jzGrp(S, 'halo 2'); db1_arcTrim(ctx, gh2, Rm * 1.5, 0, 0, 90, ST, '200*ioc((t-0.1)/0.7)'); db1_st(gh2, sc.sub, Math.max(1, 0.8 * u), 30);
