        var box = ed === 'l' ? [0, mid - span / 2, depth, mid + span / 2] : ed === 'r' ? [W - depth, mid - span / 2, W, mid + span / 2] : ed === 't' ? [mid - span / 2, 0, mid + span / 2, depth] : [mid - span / 2, H - depth, mid + span / 2, H];
