function db2_ntab(seed, x0, x1) { var I = Math.floor(x0) - 1, n = Math.floor(x1) - I + 3, o = [], k; for (k = 0; k < n; k++) o.push(jzN(db2_rs(seed, I + k))); return I + ',[' + o.join(',') + ']'; }
