function db2_pt(p) { return '[' + jzN(p[0]) + ',' + jzN(p[1]) + ']'; }
// colour as an expression literal [r,g,b,1]
function db2_cx(hex) { var c = jzHex(hex); return '[' + jzN(c[0]) + ',' + jzN(c[1]) + ',' + jzN(c[2]) + ',1]'; }
