    if (endEx != null) jzSetExpr(tr.property('ADBE Vector Trim End'), H + 'Math.max(0,Math.min(100,' + endEx + '))');
    if (startEx != null) jzSetExpr(tr.property('ADBE Vector Trim Start'), H + 'Math.max(0,Math.min(100,' + startEx + '))');
