        jzAddPath(gc, db2_arc(c0[0] - c0[2] * 0.1, c0[1] + c0[2] * 0.12, c0[2] * 0.55, 200, 290, 16), false); db2_st(gc, sc.sub, Math.max(1, u), 60, 2);
