    jzAnimator(L, 'JZ In Settle', [['ADBE Text Scale 3D', [300, 300, 100]], ['ADBE Text Position 3D', [0, -size * 0.16 / 0.175, 0]]], q + 'on?0.175*(1-e)*100:0');
