    jzAnimator(F, 'JZ In Hinge', [['ADBE Text Position 3D', [K, K, 0]]], q + 'var HS=' + eb1_arr(HS) + ',hs=HS[textIndex-1]||SZ,c=(-0.02+1.04*io3(q))*2*hs,v=' + jzN(b) + '*(hs-c)/' + jzN(K) + '*100;on?[-v,v,0]:[0,0,0]');
