    jzAnimator(B, 'JZ In Set', [['ADBE Text Opacity', 0]], eb1_hd(m) + st + 'q>0.5&&q<1?0:100');
    shade(B, 'e2');
    // per-glyph clips (layer space): L = top-left quarter, + top-right quarter after stage 1, + bottom half when done
