    var L = m.L, G = xb1_geo(m), r = G.r, sz = xb1_sz(m), C = xb1_col(m), H = m.H, s0 = xb1_s0(L), vert = G.vert, cs = m.c.seed | 0;
    var pad = sz * 0.02, x0 = r.left - pad, y0 = r.top - pad, x1 = r.left + r.width + pad, y1 = r.top + r.height + pad, bw = x1 - x0, bh = y1 - y0;
