        var L = ahr_fit(ctx, jzSplitLines(jzFlat(c.text), port ? 6 : 7), { font: font, color: ink, x: cx, y: fy + fh + ph * 0.1, track: 0.04, lead: 1.1, maxW: pw * 0.86, maxH: ph * 0.13, maxSize: pw * 0.16 });
        var bb = jzBB(L);
        jzAnimate(ctx, L, { mi: 0 });
        kids.push(L);
