        var t0 = jzFlat(c.text), units = akn_units(c, 6, 1), ki = units.length - 1;
        if (jzP(ctx, 'key', 'long') === 'long') { var bv = -1; for (i = 0; i < units.length; i++) { var v = akn_gc(units[i]) + (/[\u4E00-\u9FFF]/.test(units[i]) ? 0.5 : 0); if (v > bv) { bv = v; ki = i; } } }
