        jzTextOnPath(L, sh, HD + 'var q=cl(time/TT),sh=lrp(S0,S1,1-Math.pow(1-q,2.6))+ic(PO)*W*1.3;sh+DLP*cl((sh-LT/2-ST)/LP)-LT', ctx);
