        var font = jzFontOf(ctx, 'font', 'body'), side0 = jzP(ctx, 'side0', 1) < 0 ? -1 : 1, alt = jzP(ctx, 'alt', false);
        var colW = W * (port ? 0.86 : W / H < 1.5 ? 0.66 : 0.52), maxW = colW * 0.8;
