        var font = jzP(ctx, 'font', jzFontKeyOf(ctx.st, 'display')), fb = jzP(ctx, 'fb', jzBodyF(ctx)), ang0 = jzP(ctx, 'ang', 16), plate = jzP(ctx, 'plate', 'box');
        var speed = jzP(ctx, 'speed', 1), swap = !!jzP(ctx, 'swap', false), sep = jzP(ctx, 'sep', '\uFF0F');
