            var cp = { font: font, size: size, x: W / 2, y: H / 2, track: 0.03, lead: 1.1, name: 'zoom copy ' + k, color: sc.sub };
            if (outline) { cp.fill = false; cp.stroke = Math.max(1.2 * u, size * 0.01); cp.strokeColor = sc.sub; }
