                jzSetExpr(jzXf(L, 'ADBE Anchor Point'), HD + 'var e=oe((time-0.04)/0.7),ex=ie(PO);var off=' + jzN(D) + '*(1-e)' + sh + '+' + jzN(W * 0.4) + '*ex;[value[0]-(' + jzN((h ? -1 : 1) * dirL) + ')*off,value[1]]');
