/* ================================================================== 34 karuta \u2014 \u304B\u308B\u305F\u672D */
jzReg('layout', 'karuta', {
    plan: function (rng, cut, st) {
        return { font: rng.pick(jzFontsOf(st, ['serif', 'display'])), variant: lc2_port(cut) ? rng.pick(['single', 'pair']) : rng.pick(['pair', 'pair', 'single']),
            from: rng.pick([1, -1]), tilt: rng.range(-4, 4), art: rng.pick(['sun', 'wave', 'mount']) };
    },
    build: function (ctx) {
        var W = ctx.W, H = ctx.H, sc = ctx.sc, c = ctx.cut, u = jzU(ctx), kx = lc2_k(ctx), port = jzPortrait(ctx), HD = lc2_H(ctx), i;
        var font = jzP(ctx, 'font', jzSerifF(ctx)), pair = jzP(ctx, 'variant', 'pair') === 'pair', from = jzP(ctx, 'from', 1), tilt = jzP(ctx, 'tilt', 0), art = jzP(ctx, 'art', 'sun');
        var C = lc2_card(sc), t0 = lc2_vt(c.text), first = jzChars(t0)[0] || '', fc = [sc.accent, sc.accent2, sc.ink, C.text], frameC = C.text;
        for (i = 0; i < fc.length; i++) if (fc[i] && jzContrast(fc[i], C.fill) >= 1.3 && jzContrast(fc[i], sc.bg) >= 1.3) { frameC = fc[i]; break; }
        var red = lc2_plate(sc, [sc.accent, sc.accent2, C.text], C.fill, 1.7);
        var ch = port ? Math.min(H * (pair ? 0.42 : 0.72), W * (pair ? 0.56 : 0.8) / 0.72) : Math.min(H * 0.8, pair ? W * 0.9 / 2.2 / 0.72 : H), cw = ch * 0.72;
        var hyp = Math.sqrt(cw * cw + ch * ch);
        // a card that slaps down (slides in, settles with a wobble, impact lines); returns its rig
        function card(idx, cx, cy) {
            var t1 = idx * 0.12, SL = HD + 'var T1=' + jzN(t1) + ',e=cl((time-T1)/0.28),q=oc(e),bp=e>=1?Math.exp(-(time-T1-0.28)*14)*Math.sin((time-T1-0.28)*40)*0.02:0,eo=ic(PO),a=cl(e*3)*(1-eo);';
            var IM = lc2_S(ctx, 'impact ' + (idx + 1), cx, cy), gi = lc2_G(IM, 'impact'), ls0 = [];
            for (var j = 0; j < 10; j++) {
                var ang = j / 10 * Math.PI * 2 + 0.3, r0 = hyp * 0.55, r1 = r0 + u * 0.05, fx = Math.cos(ang) * (cw / hyp) * 1.4, fy = Math.sin(ang) * (ch / hyp) * 1.4;
                ls0.push([[fx * r0, fy * r0], [fx * r1, fy * r1]]);
            }
            var gl = lc2_lines2(gi, 'lines', ls0, sc.sub, Math.max(2 * kx, u * 0.003));
            jzAddTrimPaths(gl, SL + 'var k=(time-T1-0.26)/0.25;100*(1-cl(k))');
            lc2_gx(gi, 'sc', SL + 'var k=cl((time-T1-0.26)/0.25),s=100*(0.55+k*0.1)/0.55;[s,s]');
            jzSetExpr(jzXf(IM, 'ADBE Opacity'), SL + 'var k=(time-T1-0.26)/0.25;(k>0&&k<1)?100*(1-k):0');
            lc2_paint(IM);
            var R = lc2_S(ctx, 'karuta ' + (idx + 1), cx, cy), g = lc2_G(R, 'card');
            lc2_shadow(g, sc, -cw / 2, -ch / 2, cw, ch, cw * 0.05, u * 0.014);
            lc2_box(g, 'frame', -cw / 2, -ch / 2, cw, ch, frameC, { r: cw * 0.05 });
            lc2_box(g, 'face', -cw / 2 + cw * 0.06, -ch / 2 + cw * 0.06, cw * 0.88, ch - cw * 0.12, C.fill, { r: cw * 0.03 });
            jzSetExpr(jzXf(R, 'ADBE Position'), SL + '[value[0]+(1-q)*' + jzN(W * 0.7 * from) + ',value[1]+eo*' + jzN(H * 0.15) + ']');
            jzSetExpr(jzXf(R, 'ADBE Rotate Z'), SL + 'value+(1-q)*' + jzN(35 * from) + '+' + jzN(tilt * (idx ? -0.6 : 1)));
            jzSetExpr(jzXf(R, 'ADBE Scale'), SL + '[value[0]*(1+bp),value[1]*(1-bp)]');
            jzSetExpr(jzXf(R, 'ADBE Opacity'), SL + 'value*a');
            return { R: R, g: g, SL: SL, t1: t1, cx: cx, cy: cy };
        }
        function stat(K2, L) { lc2_kid(L, K2.R); jzSetExpr(jzXf(L, 'ADBE Opacity'), K2.SL + 'value*a'); }
        function ring(K2) {
            var Rr = cw * 0.2, ccx = cw * 0.2, ccy = -ch / 2 + cw * 0.3;
            lc2_circ(K2.g, 'ring', ccx, ccy, Rr, C.fill, { stroke: red, sw: Math.max(3 * kx, cw * 0.02) });
            return lc2_T(ctx, first, { font: font, size: Rr * 1.3, x: K2.cx + ccx, y: K2.cy + ccy, color: red });
        }
        function verse(K2, big) {
            var iw = cw * 0.72, ih = big ? ch - cw * 0.72 : ch * 0.8, vo = { vertical: true, lead: 1.3, track: 0.05 };
            var fb = lc2_fitBlock(t0, iw, ih, vo, 3), size = Math.min(fb.size, cw * 0.3), mm = lc2_meas(fb.text, size, vo);
            var y = big ? -ch / 2 + cw * 0.58 + (ih - mm.h) * 0.3 : -mm.h / 2;
            var VV = lc2_V(ctx, fb.text, { font: font, size: size, color: C.text, x: K2.cx, y: K2.cy + y, lead: 1.3, track: 0.05, name: t0 });
            lc2_kid(VV.L, K2.R); lc2_main(ctx, VV.L, K2.t1 + 0.2);
        }
        if (pair) {
            var gap = cw * 0.18, ax = port ? W / 2 : W / 2 + (cw + gap) / 2, ay = port ? H / 2 - (ch + gap) / 2 : H / 2, bx = port ? W / 2 : W / 2 - (cw + gap) / 2, by = port ? H / 2 + (ch + gap) / 2 : H / 2;
            // \u8AAD\u307F\u672D (the verse) + \u53D6\u308A\u672D (the first glyph + a picture)
            var A = card(0, ax, ay);
            lc2_paint(A.R);
            stat(A, lc2_T(ctx, '\u8AAD', { font: jzSerifF(ctx), size: cw * 0.1, x: ax + cw * 0.34, y: ay - ch / 2 + cw * 0.16, color: red }));
            verse(A, false);
            var B = card(1, bx, by), aY = ch * 0.12, aw = cw * 0.66, artC = lc2_plate(sc, [sc.accent2, sc.accent, sc.sub], C.fill, 1.3), ga = lc2_sub(B.g, 'picture');
            if (art === 'sun') { lc2_circ(ga, 'sun', 0, aY, aw * 0.26, artC, { op: 90 }); lc2_box(ga, 'horizon', -aw / 2, aY + aw * 0.2, aw, aw * 0.05, C.text, { op: 60 }); }
            else if (art === 'wave') {
                var wl = [];
                for (var j2 = 0; j2 < 3; j2++) { var pts = []; for (i = 0; i <= 20; i++) pts.push([-aw / 2 + aw * i / 20, aY + j2 * aw * 0.14 + Math.sin(i / 20 * Math.PI * 3) * aw * 0.05]); wl.push(pts); }
                lc2_lines2(ga, 'waves', wl, artC, Math.max(3 * kx, aw * 0.03), { op: 90, cap: 2 });
            } else lc2_poly(ga, 'mountain', [[-aw / 2, aY + aw * 0.3], [-aw * 0.1, aY - aw * 0.25], [aw * 0.1, aY + aw * 0.02], [aw * 0.25, aY - aw * 0.12], [aw / 2, aY + aw * 0.3]], artC, { op: 90 });
            var fl = ring(B);
            lc2_paint(B.R);
            stat(B, fl);
            return lc2_box4(ax - cw / 2, ay - ch / 2, ax + cw / 2, ay + ch / 2);
        }
        var S = card(0, W / 2, H / 2), fl2 = ring(S);
        lc2_paint(S.R);
        stat(S, fl2);
        verse(S, true);
        return lc2_box4(W / 2 - cw / 2, H / 2 - ch / 2, W / 2 + cw / 2, H / 2 + ch / 2);
    }
});

// ================================================================ pack layoutsD part 1 (AE port of src/11p_layoutsD.js, entries 1-17)
// cube, cylinder, flipCards, accordion, flag, ribbon, pendulum, pile, blocks, balloons, magnets, tiles, bulbs, ledScroll,
// billboard, crowdBubbles, crossword
//
// Techniques used here (no 3D layers \u2014 the faux 3D is done with 2D affine maps, as in the browser):
// - an affine map M = [a, b, c, d, e, f] (x' = a*x + c*y + e, y' = b*x + d*y + f) is split by aff() in the expressions into
//   Rotation * Skew * Scale: shape groups take it as their group transform, a text layer through a Transform effect.
// - deforming quads (cloth strips, ribbon segments) are pairs of triangles: a 100 px unit triangle mapped by its group
//   transform. All triangles of one surface live in sub-groups of ONE group with ONE fill, so they fill as a union (no seams).
// - "glyph layers": one glyph per line, anchor = position (layer space == comp space); per-glyph animators move / turn /
//   scale / hide each glyph, so many freely placed glyphs stay ONE editable text layer.
// - moving objects that carry a lyric glyph are separate shape layers and the text is parented to them, so the cut's
//   enter / hold / exit expressions on the text layer stay untouched.

var LD1_CY = 0.38;     // glyph centre above the baseline (em)
// expression helpers appended after jzTH(ctx): in-out cubic, affine split, colour mix
var LD1_FX = 'function iocu(x){x=cl(x);return x<0.5?4*x*x*x:1-Math.pow(-2*x+2,3)/2;}' +
    'function aff(a,b,c,d){var sx=Math.sqrt(a*a+b*b);if(sx<1e-6)sx=1e-6;var r=Math.atan2(b,a),kk=(a*c+b*d)/sx,sy=(a*d-b*c)/sx,t=Math.abs(sy)<1e-6?0:kk/sy;t=Math.max(-11,Math.min(11,t));return [r*180/Math.PI,-Math.atan(t)*180/Math.PI,sx*100,sy*100];}' +
    'function mixc(a,b,t){return [a[0]+(b[0]-a[0])*t,a[1]+(b[1]-a[1])*t,a[2]+(b[2]-a[2])*t,1];}\n';

/* ---------------------------------------------------------------- small helpers */
function ld1_H(ctx) { return jzTH(ctx) + LD1_FX; }
function ld1_mot(ctx) { return ctx.fx && ctx.fx.motion != null ? ctx.fx.motion : 0.7; }
function ld1_col(hex) { var c = jzHex(hex); return '[' + jzN(c[0]) + ',' + jzN(c[1]) + ',' + jzN(c[2]) + ',1]'; }
function ld1_box(x0, y0, x1, y1) { return { x0: x0, y0: y0, x1: x1, y1: y1, cx: (x0 + x1) / 2, cy: (y0 + y1) / 2 }; }
function ld1_stag(ctx) { return Math.max(0.005, ctx.cut.stagger || 0.04); }
function ld1_mi(ctx, t) { return Math.floor(Math.max(0, t) / ld1_stag(ctx) + 1e-6); }      // browser miAt
function ld1_plateHold(ctx) { return jzIndexOf(['still', 'jitter', 'breathe', 'glitchtick'], ctx.cut.hold || 'still') < 0; }
function ld1_light(sc) { return jzLum(sc.fg) > jzLum(sc.bg) ? sc.fg : sc.bg; }
function ld1_dark(sc) { return jzLum(sc.fg) > jzLum(sc.bg) ? sc.bg : sc.fg; }
function ld1_onCol(sc, fill) {
    var c = [sc.bg, sc.fg, sc.ink, sc.accent, sc.sub], best = null, bv = 0;
    for (var i = 0; i < c.length; i++) { if (!c[i] || String(c[i]).toUpperCase() === String(fill).toUpperCase()) continue; var k = jzContrast(c[i], fill); if (k > bv) { bv = k; best = c[i]; } }
    return bv >= 2.4 ? best : (jzLum(fill) > 0.5 ? '#111111' : '#FFFFFF');
}
function ld1_plateCol(sc, pref) { for (var i = 0; i < pref.length; i++) if (pref[i] && jzContrast(pref[i], sc.bg) >= 1.6) return pref[i]; return sc.fg; }
function ld1_shade(sc, c, s) { return s >= 0 ? jzMixHex(c, ld1_light(sc), Math.min(0.9, s)) : jzMixHex(c, ld1_dark(sc), Math.min(0.9, -s)); }
function ld1_objCols(sc) {
    var src = [sc.accent, sc.fg, sc.accent2, sc.ink, sc.sub], out = [];
    for (var i = 0; i < src.length; i++) if (src[i] && jzContrast(src[i], sc.bg) >= 1.7 && jzIndexOf(out, src[i]) < 0) out.push(src[i]);
    return out.length ? out : [sc.fg];
}
function ld1_alt(ctx) { var c = ctx.cut; if (c.lineText && jzStrip(c.lineText) !== jzStrip(c.text)) return jzFlat(c.lineText); return jzRomajiOf(ctx) || 'No.' + jzLineNo(ctx); }
function ld1_arr(a) { return jzArrExpr(a); }
function ld1_strArr(a) { var o = []; for (var i = 0; i < a.length; i++) o.push('"' + String(a[i]).replace(/\\/g, '\\\\').replace(/"/g, '\\"') + '"'); return '[' + o.join(',') + ']'; }
function ld1_sub(g, name) { var q = jzVecs(g).addProperty('ADBE Vector Group'); if (name) q.name = name; return q; }
// re-fetch a named top-level group of a shape layer (a sibling added to Contents invalidates older group references in AE)
function ld1_rg(S, name) { return S.property('ADBE Root Vectors Group').property(name); }
function ld1_gOp(g, ex) { jzSetExpr(jzGX(g).property('ADBE Vector Group Opacity'), ex); }
function ld1_gPos(g, ex) { jzSetExpr(jzGX(g).property('ADBE Vector Position'), ex); }
function ld1_gSc(g, ex) { jzSetExpr(jzGX(g).property('ADBE Vector Scale'), ex); }
function ld1_gRot(g, ex) { jzSetExpr(jzGX(g).property('ADBE Vector Rotation'), ex); }
function ld1_rr(g, w, h, r, x, y) { return jzAddRect(g, Math.max(0.5, w), Math.max(0.5, h), Math.max(0, Math.min(r, w / 2, h / 2)), x || 0, y || 0); }
