            var pk = 'function pk(q){if(!' + (peek ? 1 : 0) + ')return 0;var T=1.3,kk=Math.floor(time/T),f=time/T-kk;if(kk<1||Math.floor(hh(kk*5+' + (s % 997) + ')*' + (per * 2) + ')!==q)return 0;return f<0.25?iocu(f/0.25):f<0.6?1:1-iocu((f-0.6)/0.25);}';
