                    jzSetExpr(rc.property('ADBE Vector Rect Position'), rh + 'var a=' + (e2 ? 'C0+CNT*pw+' + jzN(cw2 / 2) : 'C0-' + jzN(cw2 / 2)) + ';' + P2('a', 'CY'));
                    jzSetExpr(rc.property('ADBE Vector Rect Size'), rh + 'var hq=' + (tall ? 'PH*(1+KP*sa)' : 'hmn') + '*1.16;' + P2(jzN(cw2), 'hq'));
