                var g = jzGrp(S, 'panel ' + (r + 1) + '.' + (j + 1)), ph2 = rh + 'var a0=C0+' + j + '*pw,a1=a0+pw,xt=' + (par === 0 ? 'a0' : 'a1') + ';';
                var gcr = ld1_sub(g, 'crease'), rcr = ld1_rr(gcr, 1, 1, 0);
                jzSetExpr(rcr.property('ADBE Vector Rect Position'), ph2 + P2('a0', 'CY'));
