            'if(f<1){var e=iq(f);return [1,f,rest,1];}var tau=(f-1)*' + fd + ';return [1,f,rest-' + jzN(size * 0.14) + '*Math.abs(Math.sin(tau*16))*Math.exp(-tau/0.09),1-0.16*Math.exp(-tau/0.05)];}';
