        var FL = jzShapeLayer(ctx, 'floor', 0, 0), gfl = jzGrp(FL, 'floor'); jzAddPath(gfl, [[W * 0.08, floorY], [W * 0.92, floorY]], false); jzAddStroke(gfl, sc.sub, Math.max(1 * ctx.u, u * 0.002));
