        for (i = 0; i < own.length; i++) if (!jzIsPunct(own[i]) && !jzIsLatin(own[i]) && '\u3041\u3043\u3045\u3047\u3049\u3063\u3083\u3085\u3087\u308E\u30A1\u30A3\u30A5\u30A7\u30A9\u30C3\u30E3\u30E5\u30E7\u30EE\u30FC'.indexOf(own[i]) < 0) pool.push(own[i]);
