            ld1_place(NG, NP); jzAnimator(NG.L, 'JZ Row Show', [['ADBE Text Opacity', 0]], TH + 'var NR=' + ld1_arr(NR) + ';(1-0.8*ra(NR[textIndex-1]))*100'); ld1_opx(ctx, NG.L, 'K');
