            jzSetExpr(jzXf(PL, 'ADBE Position'), hd + '[SX+(HX-SX)*e+(HX-' + jzN(W / 2) + ')*eo*1.4+CA*eo*DI*0.5,SY+(HY-SY)*e+(HY-' + jzN(H / 2) + ')*eo*1.4+SA*eo*DI*0.4]');
