                jzAddRect(gpat, per2 / 2, diag + size, 0, -ns / 2 * per2, 0); jzAddFill(gpat, shine ? (sc.grad ? sc.grad[1] : B) : A);
                var rs = jzVecs(gpat).addProperty('ADBE Vector Filter - Repeater'); rs.property('ADBE Vector Repeater Copies').setValue(ns);
