        var font = jzP(ctx, 'font', jzFontKeyOf(ctx.st, 'display')), text = ld2_brk(c.text, port ? 4 : 5), tr = -0.02, lead = 0.98;
        var fitW = jzP(ctx, 'crop', false) ? 1.12 : 0.9;
