            for (i = 0; i < 4; i++) { jzAddPath(gm, [[cs[i][0] - Lm, cs[i][1]], [cs[i][0] + Lm, cs[i][1]]], false); jzAddPath(gm, [[cs[i][0], cs[i][1] - Lm], [cs[i][0], cs[i][1] + Lm]], false); jzAddEllipse(gm, Lm * 0.9, Lm * 0.9, cs[i][0], cs[i][1]); }
