            if (i < n - 1) aty_grp(S, 'row ' + (i + 1), [[[x0, top + (i + 1) * rowH], [x1, top + (i + 1) * rowH]]], sc.sub, { width: lw, alpha: 0.22, gop: hd + '100*cl(' + a + ')' });
