        jzSetExpr(jzXf(S, 'ADBE Position'), hd + '[' + jzN(W) + '*(0.5+0.2*Math.sin(T*0.14+' + ph + ')),' + jzN(H) + '*(0.5+0.1*Math.sin(T*0.11+' + (ph * 2) + '))]');
        axp_fade(b, S, 1);
