function axl_H(ctx) { return jzTH(ctx) + AXL_FNS + 'var ST=' + jzN(axl_settle(ctx)) + ',t=time-ST,V=t>0?1:0,o=K,M=' + jzN(ctx.fx.motion) + ';\n'; }
