    axn_box(S, sp.x + axn_tw(ctx, pre0, fs, mf) + fs * 0.5, y1 + lh * 2 - fs * 0.55, fs * 0.55, fs * 1.1, sc.fg, 1, { opEx: '(Math.floor(time*2.6)%2===0?1:0)*' + e2 });
