    for (i = 0; i < nL; i++) { s = ''; for (j = 0; j < per; j++) s += unit[(i * per + j) % unit.length]; lines.push(jzTrim(s)); }
    for (i = 0; i < nL; i++) w = Math.max(w, axn_tw(ctx, lines[i], fs, f, 0.04));
