    if (axf_soft(m, g)) { axf_core(m, 'slice'); return; }
    var ak = Math.abs(k) * g.T / 2, lo = g.U0 - ak, hi = g.U1 + ak, N = jzClamp(Math.round((hi - lo) / (fs * 1.15)), 3, 7), sw = (hi - lo) / N;
    var nrm = Math.sqrt(k * k + 1), D = g.T + fs * 1.4;
