    jzSetExpr(jzXf(D, 'ADBE Opacity'), H + 'time>=DL&&time<DL+IN?value*0.8:0');
    axf_half(D, g, 'v', -1, g.V0, E + 'bv-V0', 'JZ In Scan Outline');
    // the fill comes back up with the bar
