    var X = axh_xf(L), rr = X.r * Math.PI / 180, ux = (x - X.a[0]) * X.s[0] / 100, uy = (y - X.a[1]) * X.s[1] / 100;
    return [X.p[0] + Math.cos(rr) * ux - Math.sin(rr) * uy, X.p[1] + Math.sin(rr) * ux + Math.cos(rr) * uy];
