    var fx = ['lp(1,0.17,io3(sg(p,0,0.4)))*(1-iq(sg(p,0.42,0.9)))', 'lp(1,0.17,io3(sg(p,0.06,0.46)))*(1-iq(sg(p,0.5,1)))'];
