    var a0 = (v ? r.top : r.left) - pad, a1 = (v ? r.top + r.height : r.left + r.width) + pad, big = (r.width + r.height) * 4 + fs * 10;
    var E0 = rev ? a1 + band * N * 1.5 : a0 - band * N * 1.5, lo = rev ? E0 : E0 - big, hi = rev ? E0 + big : E0;
    var P = null;
