        jzSetExpr(mk.property('ADBE Mask Offset'), H + 'axjP>0?' + jzN(a1 - a0 + band * N) + '*axjIo(axjG(axjP,0,0.62)):0');
        jzSetExpr(mk.property('ADBE Mask Opacity'), H + 'axjP>0?100:0');
