function axr_si(St) { return 'var si=Math.max(0,Math.min(' + (St.length - 1) + ',Math.floor(time*24+0.0001)-' + St[0].st + '));'; }
function axr_arr(name, a) { var s = [], i; for (i = 0; i < a.length; i++) s.push(jzN(a[i])); return 'var ' + name + '=[' + s.join(',') + '];'; }
