        var arg = jzN((rev ? n - 1 - i : i) / (n - 1)) + ',' + jzN(0.09 + 0.15 * axr_r(s, i, 3));
        var L = jzAdjLayer(f.comp, 'JZ FX xrColumnDrop ' + jzPad(i + 1, 2), ev.t, ev.dur);
