            ahza_op(kp, { t: 'r', cx: cx, cy: cy + R * 0.5, w: R * 1.1, h: R * 3.4, fill: dk, fop: 40 });
            ahza_op(kp, { t: 'r', cx: cx, cy: cy + R * 0.5, w: R * 0.72, h: R * 3.4, fill: dk, fop: 50 });
            var Sp = ahza_done(kp, PE + 'p>0&&p<1?100:0');
