        ahza_op(kk, { name: 'rim', t: 'p', pts: pts, closed: true, stroke: rim, sw: Math.max(1.5 * px, u * 0.004), sop: 80 });
        ahza_op(kk, { name: 'rim outer', t: 'p', pts: pts2, closed: true, stroke: rim, sw: Math.max(px, u * 0.002), sop: 30 });
