        var m = jzSize(L), slack = Math.max(0, (yBot - yTop) * 0.9 - m[1]) / 2, ty = (yTop + yBot) / 2 + jzP(ctx, 'vy', 0) * slack * 0.6;
        jzXf(L, 'ADBE Position').setValue([edge - side * m[0] / 2, ty]);
