            var OP = 'var op=0.1+0.5*ios((time-' + jzN(c.dur * jzP(ctx, 'open', 0.45)) + ')/1.6),lv=lamp(T,SD,0.8)*ioc(time/1);';
            ahza_op(k, { name: 'door', t: 'p', pts: [[dx, yb], [dx, dy], [dx + dw, dy], [dx + dw, yb]], stroke: col, sw: lw, opX: HD + '100*ioc(time/1)' });
