        var raw = jzFlat(c.text), n = jzCount(raw), unit = jzSplitLines(raw, port ? 6 : 14), lines = unit.split('\r'), Ln = lines.length;
        var K = Math.max(2, Math.min(jzP(ctx, 'k', 4) + (port && Ln === 1 ? 1 : 0), Ln === 1 ? 6 : Ln === 2 ? 3 : 2));
