        var size = jzFontSize(L0), m = jzSize(L0), rowH = Math.min(H * 0.84 / K, m[1] + size * 0.42), y0 = H / 2 - rowH * (K - 1) / 2;
        var wr = 1 + Math.min(K - 2, Math.floor(jzP(ctx, 'wr', 0.5) * (K - 1))), kind = jzP(ctx, 'kind', 'mirror');
