            gpos: [jzLerp(sx, tx, f) - Math.sin(ang) * sd * fl * 0.55, jzLerp(sy, ty, f) + Math.cos(ang) * sd * fl * 0.55], grot: (ang + sd * 0.12 + ahza_rs(s, i, 2) * 0.1) * 180 / Math.PI,
