        jzSetExpr(jzXf(G, 'ADBE Position'), HD + '[value[0]+(rn(Math.floor(ST/4)+' + (k * 31) + ',3)<0.18?(rn(ST+' + (k * 31) + ',5)*2-1)*' + jzN(size * 0.08) + ':0),value[1]]');
