            if (!ahza_over(bb, x, sp.y + R * 0.9 + Ld, x, sp.y + R * 0.9 + Ld, u * 0.02)) drips.push({ t: 'p', pts: [[x, sp.y + R * 0.9], [x, sp.y + R * 0.9 + Ld]] });
