    jzSetExpr(jzXf(Gl, 'ADBE Position'), HD + 'var a=ang*Math.PI/180;[' + jzN(x) + '+Math.sin(a)*(LL+' + jzN(r * 0.9) + '),Math.cos(a)*(LL+' + jzN(r * 0.9) + ')]');
    jzSetExpr(jzXf(Gl, 'ADBE Opacity'), HD + 'LL<=1?0:30*lv');
    jzNoGhost(Gl);
