/* ================================================================ TRANSITIONS (t.A = previous wrapper, held; t.B = this cut's wrapper, above it) */
function ahzb_thd(t) { return jzEvHead(t.t0, t.dur, ',W=' + t.W + ',H=' + t.H + ',SD=' + (((t.cut && t.cut.seed) | 0) % 9973)) + AHZB_FNS + 'var inW=time>=T0&&time<T0+TD;'; }
