    for (i = 0; i < src.length; i++) { s = jzTrim(String(src[i])); if (s) w.push(s); }
    if (jzStrip(w.join('')) !== jzStrip(text)) { w = []; src = lat ? text.split(/\s+/) : jzChunk(text); for (i = 0; i < src.length; i++) { s = jzTrim(String(src[i])); if (s) w.push(s); } }
