        var size = F.size, T = jzClamp(c.dur * 0.5, 0.5, 1.5), cx = W / 2, cy = H / 2, accC = akza_acc(sc), subC = akza_sub(sc), acc = jzP(ctx, 'acc', 0), pdir = jzP(ctx, 'dir', 1);
