    var op = 100; try { op = jzXf(L, 'ADBE Opacity').valueAtTime(0, true); } catch (e2) { try { op = jzXf(L, 'ADBE Opacity').value; } catch (e3) { op = 100; } }
    return op >= (amin == null ? 0.9 : amin) * 100 - 0.1;
