    'function ioc(x){x=cl(x);return x<0.5?4*x*x*x:1-Math.pow(-2*x+2,3)/2;}' +
    'function inE(d,dl){return oe((time-dl)/d);}function inC(d,dl){return oc((time-dl)/d);}';
