function axa_pickPlate(sc, k) { return axa_plateCol(sc, k === 'accent' ? [sc.accent, sc.ink, sc.fg] : k === 'ink' ? [sc.ink, sc.accent, sc.fg] : [sc.fg, sc.ink]); }
