    if (s.k === 'rect') jzAddRect(g, Math.max(0.01, s.w), Math.max(0.01, s.h), Math.max(0, Math.min(s.round || 0, s.w / 2, s.h / 2)), s.x + s.w / 2, s.y + s.h / 2);
    else if (s.k === 'ell') jzAddEllipse(g, s.r * 2, s.r * 2, s.x, s.y);
