        var it = { text: f.text, font: font, size: size, align: right ? 'left' : 'right', x: right ? W * 0.07 : W * 0.93, y: H / 2, color: sc.fg, lead: 1.22, track: 0.03, fitW: availW };
        var m = axa_meas(it.text, size, it);
