        axa_L(S, [[[hx0, hy], [hx0 + availW, hy]]], sc.sub, lw, 0.8, { trim: e2, n: 'head rule' });
        axa_label(ctx, 'INDEX \u2014 ' + axa_p2(B.no), right ? hx0 : hx0 + availW, hy - ls * 0.9, { align: right ? 'left' : 'right', op: axa_iC(0.3, 0.25) + '*K' });
