            it.y = foot ? footY - m.h / 2 : top + m.h / 2;
            var gk = axa_greek(S, cx, gy0, colW, Math.max(0, Math.floor((gy1 - gy0) / pitch)), pitch, dim, 0.9, axa_h(B.seed, i, 21), axa_iE(0.6, 0.15 + i * 0.1));
