            if (jzP(ctx, 'rule', true) && i > 0) axa_L(S, [[[cx - gut / 2, headY + M * 0.03], [cx - gut / 2, footY]]], sc.sub, lw, 0.7, { trim: axa_iE(0.7, 0.1 + i * 0.08), op: 'K', n: 'column rule' });
