    plan: function (rng, cut, st) { return { font: rng.pick(jzFontsOf(st, ['serif', 'display'])), corner: rng.pick(['tr', 'tr', 'tl', 'br']), tilt: rng.pick([-1.5, 0, 0, 1.5]), stack: rng.chance(0.6), k: rng.range(0.11, 0.17) }; },
