        var fl = corner.indexOf('l') >= 0, fb = corner.indexOf('b') >= 0;
        function mp(pts) { var o2 = [], q; for (q = 0; q < pts.length; q++) o2.push([fl ? x0 + x1 - pts[q][0] : pts[q][0], fb ? y0 + y1 - pts[q][1] : pts[q][1]]); return o2; }
