        if (L === 1) { ys.unshift(ys[0] - pitch * 0.3); ys.push(ys[ys.length - 1] + pitch * 0.3); }
        var labW = lab ? ls * 7 : 0, t = Math.max(3 * B.k, size * 0.045), S = axa_sheet(ctx, 'rules'), nS = [], nP = [], nD = [], full = tw - labW;
