            for (i = 0; i <= 96; i++) { var u = i / 96, kk = 1 - u * 0.55, th = u * 34 + ph; pts.push([sx + u * sw * 0.86 + Math.cos(th) * sw * 0.04 * kk, sy - (Math.sin(th) * 0.55 + Math.sin(u * 9 + ph * 2) * 0.45 + 0.3) * M * 0.036 * kk]); }
