        var size = jzFontSize(L), nl = axc_textOf(L).split('\r').length, mw = jzSize(L)[0], mh = size * (1 + (nl - 1) * 1.25), ity = y0 + bh * 0.47;
        var bb = axc_lyric(ctx, g, L, 0);
