        g0.l(0, gy, W, gy, road, lw * 2);
        for (i = 0; i < 9; i++) g0.r(-W * 0.05, gy + r * 0.35, W * 0.045, lw * 3, road, 1, { org: [0, gy + r * 0.35], dx: 'fr(' + jzN(i / 9) + '-time*0.35*' + dir + '-(1-e)*2*' + dir + ')*' + jzN(W * 1.1) });
        g0.done();
