        g.t(axc_cut(c.lineText || txt, port ? 12 : 26), x0 + sbh * 0.4, y0 + sbh / 2, { color: ink, font: jzBodyF(ctx), size: sbh * 0.34, track: 0.04, alpha: 0.75 });
