    var q = { font: o.font, size: size, x: o.x, y: o.y, track: o.track, lead: o.lead, align: o.align, name: 'copy ' + kind };
    if (kind === 'dim') { q.color = jzMixHex(sc.bg, sc.fg, 0.3); a = 0.9; }
    else if (kind === 'lines') { q.color = sc.fg; pat = 'lines'; }
