    if (which.indexOf('p') >= 0) jzAnimator(G.L, name + ' Place', [['ADBE Text Position 3D', [KB, KB, 0]]], pre + '[x/' + jzN(KB) + '*100,(y+' + jzN(AXD_CY * G.fs) + '-i*' + jzN(G.LD) + ')/' + jzN(KB) + '*100,0]');
