            jzSetExpr(jzXf(C, 'ADBE Position'), HD + TH + '[value[0],' + jzN(H / 2) + '+' + jzN(Rd) + '*Math.sin(th)]');
            jzSetExpr(jzXf(C, 'ADBE Scale'), HD + TH + '[value[0],value[1]*Math.max(0.02,Math.cos(th))]');
