        axd_g(S, 'baseline', { paths: [[[x - hw, by + size * 0.08], [x + hw, by + size * 0.08]]] }, { stroke: axd_acc(sc), w: lw * 2 }, axd_mid(HD, axd_ie(0.6, 0)));
        Lm.moveToBeginning();
        axd_anim(ctx, Lm, { mi: 0 });
