                var A = ln[i], B = ln[i + 1];
                if (A.sp) continue;
                gk++;
                if (!B || B.sp || jzIsPunct(A.ch) || jzIsPunct(B.ch) || n >= 60) continue;
                var x = V ? (A.cx + B.cx) / 2 : (A.cx + A.w / 2 + B.cx - B.w / 2) / 2, y = V ? (A.cy + A.h / 2 + B.cy - B.h / 2) / 2 : (A.cy + B.cy) / 2;
