    var A0 = a0 - pad, A1 = a1 + pad, C0 = c0 - pad, C1 = c1 + pad, am = (A0 + A1) / 2, cm = (C0 + C1) / 2, hs = Math.max(4 * m.u, m.size * 0.05);
