        var gr = atzb_box(S, 'box ' + (k + 1), hd + '[' + jzN(g.w * 0.84) + '*k,' + jzN(g.h * 0.84) + '*k]', null, { stroke: col, width: lw, gop: hd + '(PO>0&&u>=0&&u<1)?100:0' });
