        for (q = 0; q < 26; q++) { var fy = y0 + ch * (q + 0.5) / 26, fw = M * (0.006 + 0.008 * awza_r01(b.seed, q)); fl.push([x0 - fw, fy, fw, lw * 1.6]); fr.push([x0 + cw, fy, fw, lw * 1.6]); }
