        var t0 = jzFlat(b.txt), n = jzCount(t0), cols = [t0], k = 1, sh = H * (port ? 0.66 : 0.74), cx = W / 2, cy = H / 2, y0 = cy - sh / 2, C = awza_card(sc);
        var ex = jzP(ctx, 'extra', 1), size = 10;
