    var n = 0, g, i, o = JZ_DATA.orders || {};
    for (g in o) if (o.hasOwnProperty(g) && JZ_REG[g]) for (i = 0; i < o[g].length; i++) if (JZ_REG[g][o[g][i]]) n++;
